namespace Slic3r::GUI::JusPrin {

// Semantic colors for one appearance mode, resolved from
// resources/jusprin/ui/design-tokens.json. That file is the authoritative
// source; this struct only carries the values the shell consumes.
struct ShellPalette
{
    wxColour surface_canvas;
    wxColour surface_subtle;
    wxColour surface_raised;
    wxColour surface_selected;
    wxColour text_primary;
    wxColour text_secondary;
    wxColour text_on_action;
    wxColour border_subtle;
    wxColour border_strong;
    wxColour border_focus;
    wxColour action_primary;
    wxColour action_primary_hover;
    wxColour action_primary_pressed;
    wxColour action_primary_text;
    wxColour action_secondary;
    wxColour action_secondary_hover;
    wxColour action_secondary_pressed;
    wxColour action_secondary_text;
    wxColour action_secondary_border;
    wxColour action_disabled;
    wxColour action_disabled_text;
    wxColour status_warning;
    wxColour status_success;
    wxColour status_success_on_action;
    wxColour status_danger;
};

class ShellTheme
{
public:
    // Loads both semantic palettes from the packaged token file.
    // Throws std::runtime_error when the file is missing or malformed so the
    // caller can fall back to the standard Orca presentation.
    static ShellTheme load_from_resources();

    const ShellPalette& palette(bool dark) const { return dark ? m_dark : m_light; }

private:
    ShellPalette m_light;
    ShellPalette m_dark;
};

} // namespace Slic3r::GUI::JusPrin
#include "ShellTheme.hpp"

#include "libslic3r/Utils.hpp"

#include <boost/filesystem.hpp>
#include <nlohmann/json.hpp>

#include <fstream>
#include <stdexcept>

namespace Slic3r::GUI::JusPrin {

namespace {

wxColour parse_color(const nlohmann::json& tokens, const char* group, const char* name)
{
    const nlohmann::json& value = tokens.at(group).at(name);
    wxColour color(wxString::FromUTF8(value.get<std::string>()));
    if (!color.IsOk())
        throw std::runtime_error(std::string("design token ") + group + "." + name + " is not a valid color");
    return color;
}

ShellPalette parse_palette(const nlohmann::json& mode_tokens)
{
    ShellPalette palette;
    palette.surface_canvas          = parse_color(mode_tokens, "surface", "canvas");
    palette.surface_subtle          = parse_color(mode_tokens, "surface", "subtle");
    palette.surface_raised          = parse_color(mode_tokens, "surface", "raised");
    palette.surface_selected        = parse_color(mode_tokens, "surface", "selected");
    palette.text_primary            = parse_color(mode_tokens, "text", "primary");
    palette.text_secondary          = parse_color(mode_tokens, "text", "secondary");
    palette.text_on_action          = parse_color(mode_tokens, "text", "onAction");
    palette.border_subtle           = parse_color(mode_tokens, "border", "subtle");
    palette.border_strong           = parse_color(mode_tokens, "border", "strong");
    palette.border_focus            = parse_color(mode_tokens, "border", "focus");
    palette.action_primary          = parse_color(mode_tokens, "action", "primary");
    palette.action_primary_hover    = parse_color(mode_tokens, "action", "primaryHover");
    palette.action_primary_pressed  = parse_color(mode_tokens, "action", "primaryPressed");
    palette.action_primary_text     = parse_color(mode_tokens, "action", "primaryText");
    palette.action_secondary        = parse_color(mode_tokens, "action", "secondary");
    palette.action_secondary_hover  = parse_color(mode_tokens, "action", "secondaryHover");
    palette.action_secondary_pressed = parse_color(mode_tokens, "action", "secondaryPressed");
    palette.action_secondary_text   = parse_color(mode_tokens, "action", "secondaryText");
    palette.action_secondary_border = parse_color(mode_tokens, "action", "secondaryBorder");
    palette.action_disabled         = parse_color(mode_tokens, "action", "disabled");
    palette.action_disabled_text    = parse_color(mode_tokens, "action", "disabledText");
    palette.status_warning          = parse_color(mode_tokens, "status", "warning");
    palette.status_success          = parse_color(mode_tokens, "status", "success");
    palette.status_success_on_action = parse_color(mode_tokens, "status", "successOnAction");
    palette.status_danger           = parse_color(mode_tokens, "status", "danger");
    return palette;
}

} // namespace

ShellTheme ShellTheme::load_from_resources()
{
    const boost::filesystem::path path = boost::filesystem::path(resources_dir()) / "jusprin" / "ui" / "design-tokens.json";
    std::ifstream file(path.string());
    if (!file.is_open())
        throw std::runtime_error("design token file is missing: " + path.string());

    try {
        const nlohmann::json tokens = nlohmann::json::parse(file);
        ShellTheme theme;
        theme.m_light = parse_palette(tokens.at("semantic").at("light"));
        theme.m_dark  = parse_palette(tokens.at("semantic").at("dark"));
        return theme;
    } catch (const nlohmann::json::exception& error) {
        throw std::runtime_error(std::string("design token file could not be parsed: ") + error.what());
    }
}

} // namespace Slic3r::GUI::JusPrin

# JusPrin Agent UI

The local React/TypeScript application that renders the Agent conversation
pane inside `wxWebView`. It talks to OrcaSlicer exclusively through the
versioned `jusprin-agent-bridge` JSON protocol whose shared source of truth is
`resources/jusprin/agent/protocol.json`; the native side lives in
`src/slic3r/GUI/JusPrin/Agent/`.

The page renders native state and submits typed requests. It never owns an
editable copy of the project or conversation: the native `AgentHost` is
authoritative, and every reload re-runs the handshake and reconstructs the
page from the host's `state` message.

## Building

The C++ build does not require Node. The application loads the committed
single-file bundle at `resources/jusprin/agent/index.html`; rebuild and commit
that bundle whenever this package changes:

```bash
npm install
npm run build   # type-checks, then writes resources/jusprin/agent/index.html
```

The bundle must stay a single self-contained file (`vite-plugin-singlefile`):
WKWebView does not reliably load `file:` subresources.

## Testing

```bash
npm test        # vitest: protocol, bridge client, reducer, and DOM interaction tests
```

The deterministic conversation scenarios (`/fail`, `/flaky`, `/slow`) are
implemented natively in `DeterministicMockAgent.cpp` and asserted by
`tests/agent/test_agent_bridge.cpp`; the tests here exercise the page against
a scripted mock host playing the same protocol.

## Design

Colors resolve through the semantic tokens in
`resources/jusprin/ui/design-tokens.json` (imported at build time and applied
as CSS custom properties for the light and dark appearance the host reports).
Do not hard-code palette values in components.
